#!/usr/bin/env node
/**
 * Compiles packages/design-tokens/tokens.json into three artefacts:
 *
 *   apps/web/app/tokens.generated.css   CSS custom properties (light, dark, system)
 *   apps/web/lib/tokens.generated.ts    numeric scales + Tailwind fontSize map
 *   apps/android/.../Tokens.kt          Compose colours, spacing, radii, type
 *
 * Outputs live inside the consuming projects so neither client needs a resolver
 * trick to import them. All three are gitignored and regenerated by `pnpm tokens`.
 * This file has no dependencies: plain Node, no build step.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const repoRoot = resolve(here, '../..')
const tokens = JSON.parse(readFileSync(resolve(here, 'tokens.json'), 'utf8'))

const out = {
  css: resolve(repoRoot, 'apps/web/app/tokens.generated.css'),
  ts: resolve(repoRoot, 'apps/web/lib/tokens.generated.ts'),
  kotlin: resolve(repoRoot, 'apps/android/app/src/main/java/com/slot/app/core/design/Tokens.kt'),
}

const kebab = (name) => name.replace(/[A-Z]/g, (c) => `-${c.toLowerCase()}`)
const indentBy = (text, pad) =>
  text
    .split('\n')
    .map((line) => (line.length > 0 ? pad + line : line))
    .join('\n')

/* ---------------------------------------------------------------- CSS --- */

const colorVars = (set, pad = '  ') =>
  Object.entries(set)
    .map(([key, value]) => `${pad}--color-${kebab(key)}: ${value};`)
    .join('\n')

const tagVars = (set, pad = '  ') =>
  Object.entries(set)
    .map(([key, value]) => `${pad}--tag-${kebab(key)}: ${value};`)
    .join('\n')

const themeBody = (set) => {
  const [colors, tags] = set
  return [
    colorVars(colors),
    tagVars(tags),
    Object.entries(tokens.space)
      .map(([key, value]) => `  --space-${key}: ${value}px;`)
      .join('\n'),
    Object.entries(tokens.radius)
      .map(([key, value]) => `  --radius-${kebab(key)}: ${value}px;`)
      .join('\n'),
    Object.entries(tokens.type)
      .map(
        ([key, value]) =>
          `  --text-${key}-size: ${value.size}px;\n  --text-${key}-line: ${value.line}px;`,
      )
      .join('\n'),
    `  --font-sans: ${tokens.font.sans};`,
    `  --weight-regular: ${tokens.weight.regular};`,
    `  --weight-medium: ${tokens.weight.medium};`,
    `  --weight-semibold: ${tokens.weight.semibold};`,
    `  --duration-fast: ${tokens.motion.fast}ms;`,
    `  --duration-base: ${tokens.motion.base}ms;`,
    `  --ease-standard: cubic-bezier(${tokens.motion.easing.join(', ')});`,
    `  --shadow-popover: ${tokens.elevation.popover};`,
    `  --shadow-modal: ${tokens.elevation.modal};`,
  ].join('\n')
}

const lightBody = themeBody([tokens.color.light, tokens.tag.light])
const darkBody = themeBody([tokens.color.dark, tokens.tag.dark])

const css = `/* Generated from packages/design-tokens/tokens.json — do not edit. */
/* Run: pnpm tokens */

:root {
${lightBody}
  color-scheme: light;
}

.dark {
${darkBody}
  color-scheme: dark;
}

/* System preference applies unless the document explicitly opts out with .light. */
@media (prefers-color-scheme: dark) {
  :root:not(.light) {
${indentBy(darkBody, '    ')}
    color-scheme: dark;
  }
}
`

/* ---------------------------------------------------------------- TS ---- */

const ts = `/* Generated from packages/design-tokens/tokens.json — do not edit. */
/* Run: pnpm tokens */

export const tokens = ${JSON.stringify(
  {
    type: tokens.type,
    space: tokens.space,
    radius: tokens.radius,
    motion: tokens.motion,
    weight: tokens.weight,
  },
  null,
  2,
)}

export const tailwindFontSize = {
${Object.entries(tokens.type)
  .map(
    ([key, value]) =>
      `  ${JSON.stringify(key)}: ["${value.size}px", { lineHeight: "${value.line}px" }],`,
  )
  .join('\n')}
} satisfies Record<string, [string, { lineHeight: string }]>
`

/* ------------------------------------------------------------- Kotlin --- */

const composeColor = (hex) => `Color(0xFF${hex.replace('#', '').toUpperCase()})`

const kotlinColors = (set, pad) =>
  Object.entries(set)
    .map(([key, value]) => `${pad}val ${key} = ${composeColor(value)}`)
    .join('\n')

const kotlin = `package com.slot.app.core.design

import androidx.compose.animation.core.CubicBezierEasing
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp

/**
 * Generated from packages/design-tokens/tokens.json — do not edit.
 * Run: pnpm tokens
 */
object Tokens {
    object Light {
${kotlinColors(tokens.color.light, '        ')}
    }

    object Dark {
${kotlinColors(tokens.color.dark, '        ')}
    }

    object Tag {
        object Light {
${kotlinColors(tokens.tag.light, '            ')}
        }

        object Dark {
${kotlinColors(tokens.tag.dark, '            ')}
        }
    }

    object Space {
${Object.entries(tokens.space)
  .map(([key, value]) => `        val s${key} = ${value}.dp`)
  .join('\n')}
    }

    object Radius {
${Object.entries(tokens.radius)
  .map(([key, value]) => `        val ${key} = ${value}.dp`)
  .join('\n')}
    }

    object Type {
${Object.entries(tokens.type)
  .map(([key, value]) => `        val ${key} = TextStyle(fontSize = ${value.size}.sp, lineHeight = ${value.line}.sp)`)
  .join('\n')}
    }

    object Motion {
        const val fast = ${tokens.motion.fast}
        const val base = ${tokens.motion.base}
        val easing = CubicBezierEasing(${tokens.motion.easing.map((n) => `${n}f`).join(', ')})
    }
}
`

/* -------------------------------------------------------------- write --- */

for (const [path, contents] of Object.entries({
  [out.css]: css,
  [out.ts]: ts,
  [out.kotlin]: kotlin,
})) {
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, contents, 'utf8')
}

const relative = (path) => path.slice(repoRoot.length + 1)
console.log(`tokens: wrote ${Object.keys(out).length} artefacts`)
for (const path of Object.values(out)) console.log(`  ${relative(path)}`)
